/**
 * Firebase Firestore 기반 데이터 영속성 유틸리티
 * 모든 디바이스에서 동일한 데이터를 공유합니다.
 */
import { db } from '../firebase';
import {
  collection, getDocs, writeBatch, doc
} from 'firebase/firestore';

const SALES_COL = 'sales-data';
const OP_COL = 'op-data';

// ─── 배치 쓰기 헬퍼 (Firestore 배치 한도 500개) ──────────
async function batchWrite(colName, items) {
  const colRef = collection(db, colName);

  // 기존 데이터 전체 삭제
  const snap = await getDocs(colRef);
  if (snap.docs.length > 0) {
    for (let i = 0; i < snap.docs.length; i += 400) {
      const batch = writeBatch(db);
      snap.docs.slice(i, i + 400).forEach((d) => batch.delete(d.ref));
      await batch.commit();
    }
  }

  // 새 데이터 쓰기
  for (let i = 0; i < items.length; i += 400) {
    const batch = writeBatch(db);
    items.slice(i, i + 400).forEach((item) => {
      const ref = doc(db, colName, item.key);
      batch.set(ref, item);
    });
    await batch.commit();
  }
}

async function batchDelete(colName) {
  const snap = await getDocs(collection(db, colName));
  for (let i = 0; i < snap.docs.length; i += 400) {
    const batch = writeBatch(db);
    snap.docs.slice(i, i + 400).forEach((d) => batch.delete(d.ref));
    await batch.commit();
  }
}

// ─── 이지포스 판매 데이터 ───────────────────────────────

export async function saveAllData(allData) {
  try {
    await batchWrite(SALES_COL, allData);
    return true;
  } catch (err) {
    console.warn('Firestore 저장 실패:', err);
    return false;
  }
}

export async function loadAllData() {
  try {
    const snap = await getDocs(collection(db, SALES_COL));
    return snap.docs.map((d) => d.data());
  } catch (err) {
    console.warn('Firestore 불러오기 실패:', err);
    return [];
  }
}

export async function clearAllData() {
  try {
    await batchDelete(SALES_COL);
    return true;
  } catch (err) {
    console.warn('Firestore 삭제 실패:', err);
    return false;
  }
}

// ─── 영업정보 데이터 ────────────────────────────────────

export async function saveOpData(opData) {
  try {
    await batchWrite(OP_COL, opData);
    return true;
  } catch (err) {
    console.warn('Firestore 영업정보 저장 실패:', err);
    return false;
  }
}

export async function loadOpData() {
  try {
    const snap = await getDocs(collection(db, OP_COL));
    return snap.docs.map((d) => d.data());
  } catch (err) {
    console.warn('Firestore 영업정보 불러오기 실패:', err);
    return [];
  }
}

export async function clearOpData() {
  try {
    await batchDelete(OP_COL);
    return true;
  } catch (err) {
    console.warn('Firestore 영업정보 삭제 실패:', err);
    return false;
  }
}
